{const PC=[{"g": "Parcial P1a · tipo de restricción", "ctx": null, "s": [{"q": "¿Qué tipo de restricción es?", "a": "Unicidad de atributos", "b": "Regla de negocio", "w": "«es único»: la unicidad se escribe aparte en Restricciones y el atributo queda normal (codigo: String).", "x": "Restricción: «El código de Centro es único en el sistema.»"}, {"q": "¿Qué tipo de restricción es?", "a": "Integridad circular", "b": "Unicidad de atributos", "w": "«solo si ambos pertenecen al mismo Centro»: dos caminos del diagrama (Equipamiento→Centro y Espacio→Centro) tienen que llegar al mismo objeto.", "x": "Restricción: «Un Equipamiento solo puede estar habilitado para un Espacio si ambos pertenecen al mismo Centro.»"}, {"q": "¿Qué tipo de restricción es?", "a": "Atributo calculado", "b": "Regla de negocio", "w": "Dice cómo se obtiene el valor de un atributo a partir de otros.", "x": "Restricción: «precioTotal = duración * (precio espacio + equipamiento 1 * cant 1 + … )»"}, {"q": "¿Qué tipo de restricción es?", "a": "Regla de negocio", "b": "Integridad circular", "w": "Es una condición sobre valores («no puede superar»), no sobre caminos del diagrama.", "x": "Restricción: «La cantidad de asistentes de una Reserva no puede superar la capacidad del Espacio reservado.»"}, {"q": "¿Dónde vale la unicidad?", "a": "Dentro de cada Centro", "b": "En todo el sistema", "w": "«dentro del Centro al que pertenece» limita la unicidad al contenedor; para todo el sistema diría «en el sistema».", "x": "Restricción: «El número de Espacio es único dentro del Centro al que pertenece.»"}, {"q": "¿Cómo lo reflejo?", "a": "Usuario 1 — * Certificado, atributo vigente y la restricción escrita", "b": "Usuario 1 — 1 Certificado", "w": "«muchos» fija la multiplicidad *. «solo uno vigente» no cabe en una multiplicidad: va como restricción y un atributo vigente.", "x": "Restricción: «Un usuario puede tener muchos certificados, pero solo uno vigente.»"}]}, {"g": "Parcial P1a · qué elemento UML uso", "ctx": null, "s": [{"q": "¿Cómo lo modelo?", "a": "«DataType» DTFecha, usado como tipo del atributo", "b": "Clase Fecha asociada a Reserva", "w": "Sin identidad ni vida propia y solo agrupa valores: DataType. Una clase se asocia; un DataType se usa como tipo.", "x": "Dato: la Reserva tiene una fecha (día, mes, año)."}, {"q": "¿Cómo lo modelo?", "a": "«Enum» EstadoReserva (atributo estado: EstadoReserva)", "b": "Clase EstadoReserva con subclases", "w": "Conjunto cerrado de valores sin comportamiento propio: enum.", "x": "Dato: el estado de la Reserva es Confirmada, Pendiente o Cancelada."}, {"q": "¿Cómo lo modelo?", "a": "Herencia: Espacio con tres subclases", "b": "Atributo «tipo» en Espacio", "w": "Cada tipo tiene atributos propios (escenario, videoconferencia, escritorios…): subclases. Un enum solo alcanza si no hay atributos propios.", "x": "Dato: un Espacio es Auditorio, Sala de reuniones u Oficina privada, cada uno con sus atributos."}, {"q": "¿Cómo lo modelo?", "a": "Clase asociación EquipamientoEnEspacio", "b": "Atributos en Equipamiento", "w": "Los datos dependen del par (Espacio, Equipamiento), no de uno solo: clase asociación.", "x": "Dato: por cada Equipamiento habilitado en un Espacio se guarda cantidadMaxima y requiereAsistencia."}, {"q": "¿Cómo lo modelo?", "a": "Clase asociación EquipamientoEnReserva (cantidad)", "b": "Atributo cantidad en Equipamiento", "w": "La cantidad pertenece a «este equipamiento en esta reserva», no al equipamiento en general.", "x": "Dato: una Reserva incluye equipamientos, cada uno con su cantidad."}, {"q": "¿Cómo lo modelo?", "a": "Composición (rombo del lado de Centro)", "b": "Asociación simple", "w": "La parte (Espacio) no existe sin el todo (Centro): composición, con el rombo del lado del todo.", "x": "Dato: un Espacio pertenece a un Centro y no existe sin él."}]}, {"g": "Parcial P1a · multiplicidad, orden y abstracta", "ctx": null, "s": [{"q": "¿Qué multiplicidad lleva del lado Paso?", "a": "1..*", "b": "*", "w": "«uno o más» es 1..*; «cero o más» sería *.", "x": "Dato: un Proceso contiene uno o más Pasos."}, {"q": "¿Cómo expreso el orden?", "a": "{ordered} en la asociación", "b": "Atributo orden en Proceso", "w": "Que los elementos de la asociación tengan orden se marca {ordered}.", "x": "Dato: los Pasos de un Proceso siguen un orden."}, {"q": "¿Cómo dibujo Paso?", "a": "Abstracta, con subclases TareaManual y FirmaDigital", "b": "Concreta, con atributo tipo", "w": "Si nunca existe un paso genérico y cada tipo tiene atributos propios, es abstracta con subclases.", "x": "Dato: todo Paso es TareaManual o FirmaDigital; nunca un paso genérico."}, {"q": "¿Qué multiplicidad lleva Expediente → Proceso?", "a": "Cada Expediente, 1 Proceso; cada Proceso, * Expedientes", "b": "Cada Expediente, * Procesos", "w": "«instancia de un Proceso»: el expediente tiene exactamente uno; el proceso puede tener muchos expedientes.", "x": "Dato: cada Expediente es instancia de un Proceso."}, {"q": "¿Dónde va «solo si es FirmaDigital, el usuario debe tener un certificado vigente»?", "a": "En Restricciones: es una condición entre clases", "b": "Como atributo de FirmaDigital", "w": "Relaciona Usuario, Certificado y tipo de Paso: no se dibuja, se escribe como restricción.", "x": "Restricción: «Si el paso es FirmaDigital, el usuario debe tener un certificado vigente con el nivel mínimo.»"}]}, {"g": "Parcial P1b · armar el mensaje", "ctx": "Diagrama de secuencia del sistema: un actor (Cliente) y una sola línea de vida, :Sistema. Flujo: busca centro, elige centro, elige espacio, agrega equipamientos, confirma o cancela.", "s": [{"q": "¿Quién envía y a quién?", "a": "Cliente → :Sistema", "b": "Cliente → objetos del dominio", "w": "En este diagrama el sistema es una caja negra: una sola línea de vida del lado del sistema."}, {"q": "BuscarCentro: ¿qué lleva entre paréntesis?", "a": "email, fecha, hora, duracion, cantAsistentes", "b": "codigo del centro", "w": "Todavía no eligió centro: solo da los datos de la reserva."}, {"q": "BuscarCentro: ¿qué devuelve?", "a": "Set(DTCentro)", "b": "DTCentro", "w": "Devuelve varias opciones para que elija una: un conjunto."}, {"q": "SeleccionarCentro: ¿qué parámetro?", "a": "codigo: string", "b": "DTCentro", "w": "Se pasa la clave de lo que eligió de la lista anterior, no el dato completo."}, {"q": "¿Qué dice la nota del primer mensaje?", "a": "El sistema recuerda los datos de la reserva y el email del cliente", "b": "Se da de alta la reserva", "w": "La reserva todavía no se crea: solo se memoriza lo ingresado. El alta ocurre al confirmar."}, {"q": "SeleccionarEspacio: ¿qué devuelve?", "a": "Set(DTEquipamiento)", "b": "Set(DTEspacio)", "w": "Los espacios ya se devolvieron antes; ahora se ofrece el equipamiento del espacio elegido."}]}, {"g": "Parcial P1b · loop y alt", "ctx": "Diagrama de secuencia del sistema: tras elegir espacio el cliente puede agregar equipamientos y luego confirmar o cancelar.", "s": [{"q": "¿Qué fragmento uso para «puede agregar varios equipamientos»?", "a": "loop con guarda [Quiere agregar otro equipamiento]", "b": "alt", "w": "Una acción que se repite mientras el usuario quiera es un loop."}, {"q": "AñadirEquipamiento: ¿qué lleva?", "a": "(codigo: string, cant: int)", "b": "(codigo, cant, numero del espacio)", "w": "El espacio ya quedó recordado por el sistema: solo se pasa lo nuevo."}, {"q": "¿Qué fragmento uso para «confirma o cancela»?", "a": "alt con [Quiere confirmar] y [Quiere cancelar]", "b": "loop", "w": "Dos caminos excluyentes: alt, una guarda por camino."}, {"q": "Nota de Confirmar()", "a": "Se da de alta la reserva y se libera la memoria", "b": "Solo se libera la memoria", "w": "Confirmar es lo único que crea la reserva; en los dos caminos se libera lo recordado."}, {"q": "Nota de Cancelar()", "a": "Se libera la memoria", "b": "Se da de alta la reserva y se libera la memoria", "w": "Cancelar no crea nada: solo olvida lo recordado."}]}, {"g": "Parcial P1b · loop de «para cada» y DataTypes", "ctx": "Diagrama de secuencia (otro examen): iniciarExpediente(codProceso), y por cada paso sin asignar se elige un usuario.", "s": [{"q": "¿Qué guarda lleva el loop?", "a": "[Para cada paso del Proceso sin asignar]", "b": "[Quiere agregar otro paso]", "w": "Si recorre un conjunto que decide el sistema es «para cada…». Si decide el usuario sería «quiere…»."}, {"q": "asignacionUsuario: ¿qué parámetro?", "a": "email: String", "b": "DTUsuario", "w": "Se pasa la clave del usuario elegido de la lista anterior."}, {"q": "Nota de asignacionUsuario", "a": "El sistema recuerda la asociación entre el paso y el usuario", "b": "Se da de alta la asignación", "w": "Todavía no se confirmó: solo se recuerda."}, {"q": "¿Por qué DTPaso tiene subclases DTTareaManual y DTFirmaDigital?", "a": "Cada tipo de paso muestra datos propios", "b": "Porque Paso es abstracta", "w": "Si el usuario necesita ver los atributos propios de cada subtipo, el DT también hereda."}, {"q": "DTAsignacion: ¿qué contiene?", "a": "usu: DTUsuario y paso: DTPaso", "b": "Los ids de usuario y paso", "w": "Un DT agrupa los DT de lo que relaciona, no claves sueltas."}]}, {"g": "Parcial P3 · Singleton", "ctx": "class ControladorRepartos {\nprivate:\n  static ControladorRepartos *instancia;\n  ControladorRepartos();\npublic:\n  static ControladorRepartos *getInstancia();\n};", "s": [{"q": "¿El constructor es público o privado?", "a": "Privado", "b": "Público", "w": "Si fuera público cualquiera crearía otro controlador: se pierde la instancia única."}, {"q": "¿Por qué instancia es static?", "a": "Es una sola, compartida por la clase", "b": "Para que cada objeto tenga la suya", "w": "Una única instancia para todo el sistema: pertenece a la clase."}, {"q": "¿Por qué getInstancia es static?", "a": "Se llama sin tener ningún objeto todavía", "b": "Para que no modifique atributos", "w": "Es la forma de obtener el primer objeto: no puede requerir uno."}, {"q": "¿Cuándo crea el objeto getInstancia?", "a": "Solo si instancia es NULL", "b": "Siempre", "w": "Si lo creara siempre, habría un controlador nuevo por llamada."}, {"q": "¿Dónde se inicializa instancia = NULL?", "a": "En el .cpp: ControladorRepartos *ControladorRepartos::instancia = NULL;", "b": "Dentro de la clase en el .h", "w": "Un atributo static se define fuera de la clase, en el .cpp."}]}, {"g": "Parcial P3 · Clase abstracta e interfaz", "ctx": "class IRepartidor {\npublic:\n  virtual int calcularTiempoTotal(DTTandaReparto) = 0;\n  virtual ~IRepartidor();\n};\nclass RepartidorMoto : public IRepartidor {\npublic:\n  int calcularTiempoTotal(DTTandaReparto);\n};", "s": [{"q": "¿Qué significa = 0?", "a": "Método puro: la clase no se instancia y las subclases deben implementarlo", "b": "El método devuelve 0", "w": "= 0 convierte a la clase en abstracta."}, {"q": "¿Para qué ~IRepartidor es virtual?", "a": "Para que delete sobre un IRepartidor* llame al destructor de la subclase real", "b": "Para que no se pueda destruir", "w": "Sin virtual, delete por puntero base solo ejecutaría el destructor de la base."}, {"q": "¿Hace falta escribir ~IRepartidor en el .cpp?", "a": "Sí, aunque tenga el cuerpo vacío", "b": "No, al ser virtual ya existe", "w": "Un destructor declarado debe estar definido: en IRepartidor.cpp va IRepartidor::~IRepartidor() {}."}, {"q": "RepartidorMoto: ¿puede instanciarse?", "a": "Sí: implementa el método puro", "b": "No: hereda de una abstracta", "w": "Una subclase que implementa todos los métodos puros es concreta."}, {"q": "¿Qué tipo declaro para guardar un RepartidorMoto o un RepartidorBicicleta?", "a": "IRepartidor *", "b": "RepartidorMoto *", "w": "Con el puntero a la base el mismo código funciona con cualquier subclase."}]}, {"g": "Parcial P3 · Quién libera la memoria", "ctx": "int ControladorRepartos::calcularTiempoTotal(DTTandaReparto datos) {\n  IRepartidor *repartidor = generador->obtenerRepartidor(datos);\n  int tiempo = repartidor->calcularTiempoTotal(datos);\n  delete repartidor;\n  return tiempo;\n}", "s": [{"q": "obtenerRepartidor hace new. ¿Quién hace el delete?", "a": "Quien lo recibió y terminó de usarlo: el Controlador", "b": "El generador, antes de devolverlo", "w": "Si lo borrara antes de devolver, el Controlador recibiría un puntero muerto."}, {"q": "¿Por qué se guarda el resultado en tiempo antes del delete?", "a": "Después de return no se ejecuta nada más", "b": "Para que el delete sea más rápido", "w": "Se calcula, se libera y recién ahí se retorna."}, {"q": "Multiparte guarda vector<Simple *> partes, creadas en altaPaquete para esa Multiparte. ¿Las borra en su destructor?", "a": "Sí: son suyas", "b": "No: las borra el Controlador", "w": "Se crearon solo para ella y nadie más las usa: es dueña.", "x": "Multiparte::~Multiparte() { ... }"}, {"q": "Simple guarda vector<Articulo *>. ¿Los borra en su destructor?", "a": "No: los Articulos viven en el map del Controlador", "b": "Sí: guarda punteros", "w": "Son punteros compartidos; borrarlos rompería los demás paquetes y el Controlador.", "x": "Simple guarda vector<Articulo *> artsPaquete; los Articulos están en map<int, Articulo *> articulos del Controlador."}, {"q": "eliminarPaquete(int): ¿qué hago con paquetes[id]?", "a": "delete y luego erase", "b": "Solo erase", "w": "erase saca el puntero del map pero no libera el objeto; con delete (destructor virtual) también se liberan sus partes.", "x": "Controlador guarda map<int, Paquete *> paquetes."}]}, {"g": "Parcial P3 · Herencia y constructores", "ctx": "class Paquete {\nprivate: int idPaquete; string descripcion; int idCliente;\npublic: Paquete(int, string, int); virtual ~Paquete(); virtual int cantArticulos() = 0;\n};\nclass Simple : public Paquete { ... Simple(int, string, int); }", "s": [{"q": "En el constructor de Simple, ¿cómo inicializo idPaquete?", "a": "Con Paquete(idP, desc, idCli) en la lista de inicialización", "b": "idPaquete = idP en el cuerpo", "w": "idPaquete es privado de Paquete: la subclase no lo toca, llama al constructor de la base."}, {"q": "¿Qué clase implementa cantArticulos con artsPaquete.size()?", "a": "Simple", "b": "Paquete", "w": "Paquete es abstracta (= 0): cada subclase da su versión."}, {"q": "¿Cómo cuenta Multiparte sus artículos?", "a": "Suma partes[i]->cantArticulos() de cada parte", "b": "Cuenta los Articulos directamente", "w": "Sus partes son Simple: ya saben contar los suyos."}, {"q": "Controlador::cantArticulos(id) hace paquetes[id]->cantArticulos(). ¿Hace falta saber si es Simple o Multiparte?", "a": "No: el método virtual elige la versión", "b": "Sí: hay que preguntar el tipo", "w": "Es polimorfismo: se resuelve en ejecución según el objeto real."}]}, {"g": "Parcial P3 · Controlador: de datos a objetos", "ctx": "void Controlador::altaPaquete(int idPaq, string desc, int idCli, vector<vector<int>> partes) {\n  if (partes.size() == 1) { Simple *s = new Simple(idPaq, desc, idCli); ... paquetes[idPaq] = s; }\n  else { Multiparte *m = new Multiparte(idPaq, desc, idCli); ... paquetes[idPaq] = m; }\n}", "s": [{"q": "¿Qué decide si creo Simple o Multiparte?", "a": "Los datos recibidos: cuántas partes llegan", "b": "Un atributo tipo del Paquete", "w": "El Controlador elige la subclase según lo que recibe y guarda el resultado como Paquete *."}, {"q": "¿Por qué se puede hacer paquetes[idPaq] = s si el map es de Paquete *?", "a": "Un puntero a la subclase es también un puntero a la base", "b": "Porque s es un Paquete", "w": "Conversión implícita hacia la base: Simple* → Paquete*."}, {"q": "Al agregar artículos a Simple: s->agregarArticulo(articulos[id]). ¿Se crean artículos nuevos?", "a": "No: se busca en el map el puntero al ya existente", "b": "Sí: new Articulo", "w": "El Articulo se registró antes; Simple solo lo referencia."}, {"q": "En Multiparte, ¿por qué se crea un Simple por cada vector interno?", "a": "Cada vector es una parte con sus propios artículos", "b": "Para repetir el paquete", "w": "partes es vector<Simple *>: un Simple por parte."}, {"q": "calcularMontosPorPedido(datos) del Controlador: ¿quién hace el cálculo?", "a": "El objeto del dominio: tandas[id]->calcularMontosPorPedido()", "b": "El propio Controlador", "w": "El Controlador busca el objeto y delega; la lógica vive en la clase que tiene los datos."}]}];PC.forEach(c=>SWC.push(sw("p4",c.g,c.ctx,c.s.map(o=>Object.assign(st(o.q,o.a,o.b,o.w,""),o.x?{x:o.x}:{})))))}
